"""Vercel entrypoint for the IMAP FastAPI comparison app.

The original DRF and FastAPI implementations remain unchanged; this module only exposes
FastAPI at Vercel's conventional Python entrypoint and serves an interactive project dashboard.
"""
from fastapi.responses import HTMLResponse
from fastapi_app.main import app


DASHBOARD = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>IMAP — DRF vs FastAPI</title>
<style>
:root{--bg:#071018;--panel:#0c1823;--panel2:#101f2b;--text:#eef6f7;--muted:#8fa5b2;--green:#44b78b;--teal:#14b8a6;--cyan:#58d5ff;--line:#1b3442;--danger:#ff6b6b;--gold:#ffd166}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 80% 0,#123143 0,transparent 35%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
a{color:inherit}.nav{position:sticky;top:0;z-index:20;display:flex;gap:16px;align-items:center;padding:14px 5vw;background:rgba(7,16,24,.86);backdrop-filter:blur(14px);border-bottom:1px solid var(--line);overflow:auto}.brand{font-weight:800;white-space:nowrap;margin-right:auto}.brand b{color:var(--cyan)}.nav a{text-decoration:none;color:var(--muted);font-size:13px;white-space:nowrap}.nav a:hover{color:#fff}.wrap{width:min(1180px,92vw);margin:auto}.hero{min-height:78vh;display:grid;grid-template-columns:1.1fr .9fr;gap:34px;align-items:center;padding:80px 0 50px}.eyebrow,.badge{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:#0b1721;padding:7px 11px;border-radius:999px;color:#b8cbd5;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--teal);box-shadow:0 0 16px var(--teal)}h1{font-size:clamp(48px,7vw,92px);line-height:.95;margin:20px 0;letter-spacing:-.055em}.grad{background:linear-gradient(90deg,var(--green),var(--cyan));-webkit-background-clip:text;color:transparent}.lead{color:#a8bcc7;font-size:18px;line-height:1.7;max-width:760px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.btn{border:1px solid var(--line);background:#112330;color:#fff;padding:12px 16px;border-radius:12px;cursor:pointer;font-weight:700;text-decoration:none}.btn.primary{background:linear-gradient(90deg,#198b68,#0f8f8a);border:none}.server-stage{border:1px solid var(--line);background:linear-gradient(180deg,#0d1a25,#09131b);border-radius:24px;padding:22px;box-shadow:0 28px 80px #0007}.server-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.server{border:1px solid var(--line);border-radius:18px;padding:18px;min-height:170px;position:relative;overflow:hidden}.server h3{margin:0 0 8px}.server.drf{box-shadow:inset 0 0 0 1px #44b78b22}.server.fast{box-shadow:inset 0 0 0 1px #14b8a622}.pulse{position:absolute;width:9px;height:9px;border-radius:50%;background:var(--cyan);animation:fly 2.5s linear infinite;top:115px;left:-12px}@keyframes fly{to{left:105%}}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:14px}.metric{background:#0a141d;border:1px solid var(--line);border-radius:14px;padding:13px}.metric strong{font-size:20px;display:block}.metric small{color:var(--muted)}section{padding:70px 0;border-top:1px solid #112633}h2{font-size:clamp(32px,4vw,54px);margin:0 0 12px;letter-spacing:-.035em}.sub{color:var(--muted);max-width:800px;line-height:1.7;margin-bottom:28px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{border:1px solid var(--line);background:linear-gradient(180deg,#0c1923,#09141c);border-radius:18px;padding:20px}.card h3{margin-top:0}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#061019;border:1px solid #18303d;border-radius:12px;padding:14px;white-space:pre-wrap;color:#c7e2ea;min-height:100px}.endpoint{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:8px 0;padding:12px;border:1px solid var(--line);border-radius:12px}.method{font-weight:800;color:var(--teal)}.flow{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:15px}.arrow{font-size:30px;color:var(--cyan)}.bar{height:11px;background:#0b1319;border:1px solid var(--line);border-radius:999px;overflow:hidden}.fill{height:100%;width:0;transition:width 1.4s cubic-bezier(.2,.8,.2,1)}.fill.drf{background:var(--green)}.fill.fast{background:var(--teal)}.result-line{display:grid;grid-template-columns:145px 1fr 80px;gap:12px;align-items:center;margin:12px 0}.timeline{display:grid;gap:7px}.lane{height:28px;border:1px solid var(--line);border-radius:8px;background:#08131b;position:relative;overflow:hidden}.work{height:100%;border-radius:7px;background:linear-gradient(90deg,#256d57,#44b78b);position:absolute;left:0}.async .work{background:linear-gradient(90deg,#0f766e,#22c7b7)}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.select,input,textarea{background:#08131b;color:#fff;border:1px solid var(--line);border-radius:10px;padding:11px 12px}.tabs{display:flex;gap:8px;flex-wrap:wrap}.tab{padding:9px 12px;border-radius:10px;border:1px solid var(--line);background:#0a151e;color:#b4c5cd;cursor:pointer}.tab.active{border-color:#2aa98d;color:#fff;background:#103329}.compare{display:grid;grid-template-columns:1fr 1fr;gap:14px}.kpi{font-size:34px;font-weight:800}.muted{color:var(--muted)}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:5px 9px;font-size:11px;color:#a9bdc7}.truth{border-left:4px solid var(--gold);padding-left:16px}.decision label{display:flex;gap:9px;align-items:center;margin:10px 0;color:#c7d4da}.winner{font-size:38px;font-weight:900;margin:8px 0}.footer{padding:40px 0 70px;color:var(--muted);text-align:center}@media(max-width:800px){.hero,.grid,.grid3,.compare,.flow{grid-template-columns:1fr}.arrow{transform:rotate(90deg);text-align:center}.metrics{grid-template-columns:1fr 1fr}.result-line{grid-template-columns:110px 1fr 60px}.nav{padding-left:4vw}.hero{padding-top:50px}}
</style>
</head>
<body>
<nav class="nav"><div class="brand">IMAP <b>Lab</b></div><a href="#overview">Overview</a><a href="#api">API Lab</a><a href="#bench">Benchmark</a><a href="#async">Async Demo</a><a href="#validation">Validation</a><a href="#code">Code</a><a href="#choose">Choose</a><a href="#conclusion">Conclusion</a></nav>
<main class="wrap">
<section class="hero" id="overview">
<div><span class="eyebrow"><span class="dot"></span> Interactive research dashboard</span><h1>Same API.<br><span class="grad">Two frameworks.</span></h1><p class="lead">We built the same Countries REST API in Django REST Framework and FastAPI, then compared development footprint, validation, documentation, CRUD throughput, latency and concurrent I/O behaviour.</p><div class="actions"><a class="btn primary" href="#bench">Run experiment replay</a><a class="btn" href="/docs">Open FastAPI docs</a><a class="btn" href="/countries">View countries API</a></div></div>
<div class="server-stage"><div class="server-row"><div class="server drf"><span class="pill">DRF</span><h3>Django REST Framework</h3><p class="muted">Serializer-driven validation, Django ecosystem, sync worker benchmark.</p><div class="pulse"></div></div><div class="server fast"><span class="pill">FASTAPI</span><h3>FastAPI</h3><p class="muted">Type-hint validation, automatic docs and native async I/O.</p><div class="pulse" style="animation-delay:.7s"></div></div></div><div class="metrics"><div class="metric"><strong>30</strong><small>sample countries</small></div><div class="metric"><strong>4</strong><small>matched endpoints</small></div><div class="metric"><strong>20</strong><small>concurrency</small></div><div class="metric"><strong>3000</strong><small>requests/scenario</small></div></div></div>
</section>
<section><h2>How the experiment works</h2><p class="sub">The same data and API contract are exposed through two implementations, then measured using the same benchmark client. The frontend below replays the recorded results; it does not pretend to rerun the original controlled 3,000-request benchmark in your browser.</p><div class="flow"><div class="card"><h3>Shared input</h3><p>30-country in-memory dataset with name, cca2, cca3, region, population and area.</p></div><div class="arrow">→</div><div class="card"><h3>Matched implementations</h3><p>DRF and FastAPI expose equivalent endpoints and validation rules.</p></div></div><div class="grid3" style="margin-top:16px"><div class="card"><h3>Speed</h3><p>Throughput, p50 and p95 latency.</p></div><div class="card"><h3>Validation</h3><p>Same invalid inputs, different error structures.</p></div><div class="card"><h3>Developer experience</h3><p>Code size and API documentation setup.</p></div></div></section>
<section id="api"><h2>Interactive API playground</h2><p class="sub">Choose an example request and compare the response style. The live FastAPI deployment remains available through the real API links above.</p><div class="grid"><div class="card"><div class="controls"><select id="apiFramework" class="select"><option value="fast">FastAPI</option><option value="drf">DRF replay</option></select><select id="apiScenario" class="select"><option value="india">GET /countries/IN</option><option value="filter">GET /countries?region=Asia&min_population=1000000</option><option value="invalid">POST /countries — invalid body</option></select><button class="btn primary" onclick="sendDemo()">Send request</button></div><div id="requestBox" class="code">Select a scenario and press Send request.</div></div><div class="card"><h3>Response</h3><div id="responseBox" class="code">Waiting...</div></div></div></section>
<section id="bench"><h2>CRUD benchmark replay</h2><p class="sub"><span class="badge">RECORDED RESULT REPLAY</span> These bars animate values from the committed benchmark runs. Ordinary CRUD performance was broadly comparable; the biggest stable gap was the 30-item list.</p><button class="btn primary" onclick="runBench()">▶ Run benchmark replay</button><div class="card" style="margin-top:16px"><div class="result-line"><b>Country detail</b><div class="bar"><div id="d1" class="fill drf"></div></div><span>DRF 566*</span></div><div class="result-line"><b></b><div class="bar"><div id="f1" class="fill fast"></div></div><span>Fast 543*</span></div><div class="result-line"><b>30-item list</b><div class="bar"><div id="d2" class="fill drf"></div></div><span>DRF 421</span></div><div class="result-line"><b></b><div class="bar"><div id="f2" class="fill fast"></div></div><span>Fast 540*</span></div><div class="result-line"><b>Filtered list</b><div class="bar"><div id="d3" class="fill drf"></div></div><span>DRF 500*</span></div><div class="result-line"><b></b><div class="bar"><div id="f3" class="fill fast"></div></div><span>Fast 498*</span></div><p class="muted">*Approximate midpoint of the two committed runs, used only for this visual replay. Exact run values are documented in the project comparison report.</p></div><div class="grid" style="margin-top:16px"><div class="card"><div class="kpi">~400–600 req/s</div><p class="muted">Normal CRUD throughput range for both frameworks in this experiment.</p></div><div class="card"><div class="kpi">FastAPI lower p50, higher p95</div><p class="muted">Latency distributions differed; the cause of FastAPI's higher recorded p95 was not diagnosed.</p></div></div></section>
<section id="async"><h2>Sync vs async simulation</h2><p class="sub">This is the most important visual experiment. Twenty requests each wait 0.2 seconds. One synchronous DRF worker queues them; FastAPI async overlaps the waits. Switch DRF to 20 threads and the gap nearly disappears.</p><div class="controls"><button class="btn primary" onclick="runAsync('sync')">DRF: 1 sync worker</button><button class="btn" onclick="runAsync('threads')">DRF: 20 threads</button><button class="btn" onclick="runAsync('fast')">FastAPI: async</button></div><div class="grid"><div class="card"><h3 id="laneTitle">Choose a configuration</h3><div id="lanes" class="timeline"></div></div><div class="card"><span class="pill">RECORDED RESULT</span><div id="asyncKpi" class="winner">—</div><p id="asyncText" class="muted">The animation will explain why concurrency configuration matters.</p></div></div><div class="card truth" style="margin-top:16px"><b>Key finding:</b> 1 DRF sync worker ≈ 4.9 req/s; DRF with 20 threads ≈ 92.2 req/s; FastAPI async ≈ 93.8 req/s. The huge initial gap is primarily a concurrency/configuration effect, not proof that FastAPI is inherently 20× faster.</div></section>
<section id="validation"><h2>Validation lab</h2><p class="sub">Both frameworks enforce comparable rules, but they report invalid input differently.</p><div class="tabs"><button class="tab active" onclick="validateCase(this,'code')">Bad country code</button><button class="tab" onclick="validateCase(this,'population')">Negative population</button><button class="tab" onclick="validateCase(this,'region')">Invalid region</button></div><div class="compare" style="margin-top:16px"><div class="card"><h3>DRF — HTTP 400</h3><div id="drfVal" class="code"></div></div><div class="card"><h3>FastAPI — HTTP 422</h3><div id="fastVal" class="code"></div></div></div></section>
<section id="code"><h2>Code & docs comparison</h2><p class="sub">FastAPI was smaller in this experiment, while DRF carries more Django bootstrap and serializer structure. DRF's ecosystem becomes especially valuable in database-heavy applications.</p><div class="grid"><div class="card"><span class="pill">DRF</span><div class="winner" style="color:var(--green)">101 lines</div><p class="muted">About 25 lines are Django bootstrap/configuration. Without that overhead, roughly 75 lines.</p><div class="code">Serializer classes\nDjango settings/bootstrap\nExplicit schema integration\nGunicorn benchmark server</div></div><div class="card"><span class="pill">FASTAPI</span><div class="winner" style="color:var(--teal)">50 lines</div><p class="muted">Constraints can be declared directly using type hints and Pydantic models.</p><div class="code">Type hints + Pydantic\n/docs built in\n/redoc built in\n/openapi.json built in\nUvicorn benchmark server</div></div></div></section>
<section id="choose"><h2>Which framework should I choose?</h2><p class="sub">Select the priorities for a hypothetical project and let the dashboard score the fit.</p><div class="grid"><div class="card decision"><label><input type="checkbox" value="drf" onchange="choose()"> Database-heavy CRUD</label><label><input type="checkbox" value="drf" onchange="choose()"> Built-in admin / Django ORM</label><label><input type="checkbox" value="drf" onchange="choose()"> Existing Django ecosystem</label><label><input type="checkbox" value="fast" onchange="choose()"> ML / AI model API</label><label><input type="checkbox" value="fast" onchange="choose()"> Async external-service calls</label><label><input type="checkbox" value="fast" onchange="choose()"> Lightweight microservice</label><label><input type="checkbox" value="fast" onchange="choose()"> WebSockets / streaming emphasis</label></div><div class="card"><span class="pill">RECOMMENDATION</span><div id="winner" class="winner">Balanced</div><p id="winnerText" class="muted">Choose requirements to see the recommendation.</p></div></div></section>
<section id="conclusion"><h2>Conclusion</h2><div class="grid"><div class="card"><h3>What FastAPI did well</h3><p>Smaller implementation, type-driven validation, automatic docs and straightforward async I/O.</p></div><div class="card"><h3>What DRF did well</h3><p>Mature Django ecosystem, ORM, admin, auth, permissions and a strong fit for database-centric applications.</p></div></div><div class="card" style="margin-top:16px"><span class="badge">FINAL VERDICT</span><div class="winner">There is no universal winner.</div><p class="lead">For ordinary CRUD, performance was close enough that raw speed was not the deciding factor. Framework choice should follow application requirements: FastAPI for lightweight API-first and async services; DRF for larger Django and database-centric systems.</p></div></section>
<div class="footer">IMAP Project · Django REST Framework vs FastAPI · Interactive experiment dashboard</div>
</main>
<script>
function sendDemo(){const fw=document.getElementById('apiFramework').value,s=document.getElementById('apiScenario').value,req=document.getElementById('requestBox'),res=document.getElementById('responseBox');let request='',response='';if(s==='india'){request='GET /countries/IN';response=JSON.stringify({name:'India',cca2:'IN',cca3:'IND',region:'Asia',population:'sample dataset value'},null,2)}else if(s==='filter'){request='GET /countries?region=Asia&min_population=1000000';response=JSON.stringify([{name:'India',region:'Asia'},{name:'Japan',region:'Asia'},'…'],null,2)}else{request='POST /countries\n{ "cca2": "IND", "population": -10 }';response=fw==='drf'?JSON.stringify({cca2:['Ensure this field has no more than 2 characters.'],population:['Ensure this value is greater than or equal to 0.']},null,2):JSON.stringify({detail:[{loc:['body','cca2'],msg:'String should match pattern',type:'string_pattern_mismatch'},{loc:['body','population'],msg:'Input should be greater than or equal to 0',type:'greater_than_equal'}]},null,2)}req.textContent=(fw==='fast'?'FastAPI':'DRF replay')+'\n'+request;res.textContent=(s==='invalid'?(fw==='fast'?'422 Unprocessable Entity':'400 Bad Request'):'200 OK')+'\n\n'+response}
function runBench(){[['d1',82],['f1',79],['d2',62],['f2',80],['d3',74],['f3',73]].forEach(([id,w],i)=>setTimeout(()=>document.getElementById(id).style.width=w+'%',i*120))}
function runAsync(mode){const lanes=document.getElementById('lanes');lanes.innerHTML='';const title=document.getElementById('laneTitle'),k=document.getElementById('asyncKpi'),t=document.getElementById('asyncText');for(let i=0;i<20;i++){const lane=document.createElement('div');lane.className='lane '+(mode==='fast'?'async':'');const work=document.createElement('div');work.className='work';if(mode==='sync'){work.style.left=(i*4.5)+'%';work.style.width='5%'}else{work.style.left=(i%4)*2+'%';work.style.width='62%'}lane.appendChild(work);lanes.appendChild(lane)}if(mode==='sync'){title.textContent='DRF — 1 synchronous worker';k.textContent='≈ 4.9 req/s';t.textContent='Requests queue because the single worker is occupied while each request waits.'}else if(mode==='threads'){title.textContent='DRF — 20 Gunicorn threads';k.textContent='≈ 92.2 req/s';t.textContent='Threads allow the same synchronous app to overlap many waiting requests.'}else{title.textContent='FastAPI — async event loop';k.textContent='≈ 93.8 req/s';t.textContent='At await points, the event loop can serve other requests while I/O is waiting.'}}
const vals={code:[`{"cca2":["Ensure this field has no more than 2 characters."]}`,`{"detail":[{"loc":["body","cca2"],"msg":"String should match pattern","type":"string_pattern_mismatch"}]}`],population:[`{"population":["Ensure this value is greater than or equal to 0."]}`,`{"detail":[{"loc":["body","population"],"msg":"Input should be greater than or equal to 0","type":"greater_than_equal"}]}`],region:[`{"region":["\"Moon\" is not a valid choice."]}`,`{"detail":[{"loc":["body","region"],"msg":"Input should be a valid region","type":"enum"}]}`]};function validateCase(el,key){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');document.getElementById('drfVal').textContent=vals[key][0];document.getElementById('fastVal').textContent=vals[key][1]}
function choose(){let d=0,f=0;document.querySelectorAll('.decision input:checked').forEach(x=>x.value==='drf'?d++:f++);const w=document.getElementById('winner'),txt=document.getElementById('winnerText');if(d===f){w.textContent='Balanced';txt.textContent='Both frameworks can work; surrounding ecosystem and team experience should decide.'}else if(d>f){w.textContent='DRF';txt.textContent='Your priorities lean toward Django’s batteries-included database and application ecosystem.'}else{w.textContent='FastAPI';txt.textContent='Your priorities lean toward a lightweight, API-first service with strong async ergonomics.'}}
validateCase(document.querySelector('.tab'),'code');
</script>
</body></html>'''


@app.get("/", response_class=HTMLResponse, include_in_schema=False)
async def project_home():
    return HTMLResponse(DASHBOARD)
